 "content": "from collections import Counter


def transform(grid):
    """Compare two equal-sized panels: equal cells become 3, disagreements use their shared color."""
    h, w = len(grid), len(grid[0])
    candidates = []
    for c in range(w):
        if c > 0 and w - c - 1 == c and len({grid[r][c] for r in range(h)}) == 1:
            candidates.append(([row[:c] for row in grid], [row[c + 1:] for row in grid]))
    for r in range(h):
        if r > 0 and h - r - 1 == r and len(set(grid[r])) == 1:
            candidates.append((grid[:r], grid[r + 1:]))
    if not candidates:
        raise ValueError("No uniform separator with equal panels")
    a, b = candidates[0]
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    bg = Counter(v for panel in (a, b) for row in panel for v in row if v in shared).most_common(1)[0][0]
    return [[3 if a[r][c] == b[r][c] else bg for c in range(len(a[r]))]
            for r in range(len(a))]

if __name__ == '__main__':
    import ast, sys
    print(transform(ast.literal_eval(sys.stdin.read())))
